(async () => {
  const H = await import('/history/index.ts'); const S = await import('/state/index.ts');
  const w = S.useHistoryStore.getState().world.value; const n = H.worldNow();
  const beat = n.beats[n.beats.length - 1];
  const opened = beat.body.slots.map(s => s.slot);
  const free = [0, 1, 2, 3, 4, 5].find(s => !opened.includes(s));
  const cited = n.events[beat.body.slots[0].cite].label;
  const r = await window.seed.world.append(w.worldId, { kind: 'rumor', body: { beat: beat.id, slot: free, text: 'They say ' + cited + ' was here.' }, seen: n.head.n });
  return JSON.stringify({ beat: beat.id.slice(0, 12), n: beat.n, opened, tried: free, cited, result: r.ok ? 'written ' + r.value.id : r.error.code + ': ' + r.error.message, head: H.worldNow().head.n });
})()
